V C_NativeUnits::m_checked_ticks(const Args& A) {
    V L_engine = A.get(0, SY("engine"), nullptr, "checked_ticks");
    V L_count = A.get(1, SY("count"), nullptr, "checked_ticks");
    V L_name = A.get(2, SY("name"), nullptr, "checked_ticks");
    V L_error;
    V L_tb;
    try {
        (void)(m_ticks(Args{L_engine, L_count}));
    } catch (PyError& exc_) {
        if (exc_.matches("Exception")) {
            L_error = py::exc_value(exc_);
            L_tb = pvz::getattr(L_error, SY("__traceback__"));
            while ((pvz::getattr(L_tb, SY("tb_next"))).truthy()) {
                L_tb = pvz::getattr(L_tb, SY("tb_next"));
            }
            (void)(py::m_append(a_records, py_dict({{SV("case"), L_name}, {SV("success"), V(false)}, {SV("error"), py::repr(L_error)}, {SV("code"), pvz::getattr(pvz::getattr(pvz::getattr(L_tb, SY("tb_frame")), SY("f_code")), SY("co_name"))}, {SV("offset"), pvz::getattr(L_tb, SY("tb_lasti"))}})));
            throw;
        }
        else throw;
    }
    (void)(py::m_append(a_records, py_dict({{SV("case"), L_name}, {SV("success"), V(true)}, {SV("ticks"), L_count}, {SV("plants"), py::len(rdm(pvz::getattr(L_engine, SY("g")), &Obj::植物, SV("植物")))}, {SV("zombies"), py::len(rdm(pvz::getattr(L_engine, SY("g")), &Obj::僵尸, SV("僵尸")))}, {SV("entities"), py::len(rd(pvz::getattr(L_engine, SY("g")), SV("实体")))}, {SV("draw_commands"), py::len(pvz::getattr(pvz::getattr(L_engine, SY("recorder")), SY("commands")))}})));
    return V::none();
}

